let birthdayShown=false;$('continue').onclick=()=>{dialog.close();if(game.complete){if(!birthdayShown){birthdayShown=true;final=true;$('quest').hidden=true;$('continue').textContent="\u0415\u0449\u0451 \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0431\u0440\u043e\u0434\u0438\u0442\u044c \u2727";openStory("\u0421 \u0434\u043d\u0451\u043c \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u041c\u0430\u0448!","\u0422\u044b \u043a\u0430\u043a-\u0442\u043e \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u043b\u0430 \u043e \u0441\u0432\u043e\u0435\u0439 \u043c\u0435\u0447\u0442\u0435 \u2014 \u043a\u043e\u0444\u0435\u0439\u043d\u0435 \u0438 \u0430\u0440\u0442-\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u0435 \u0432 \u0433\u043e\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u0441\u0442\u0438\u043b\u0435.\n\n\u0418 \u043c\u043d\u0435 \u0437\u0430\u0445\u043e\u0442\u0435\u043b\u043e\u0441\u044c \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0444\u0430\u043d\u0442\u0430\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c.\n\n\u0422\u0430\u043a \u043f\u043e\u044f\u0432\u0438\u043b\u0441\u044f \u044d\u0442\u043e\u0442 \u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0439 \u0434\u043e\u043c \u043d\u0430 \u043a\u043e\u043b\u0451\u0441\u0430\u0445. \u0421 \u043c\u043e\u0440\u0435\u043c \u043d\u0430 \u0441\u0442\u0435\u043d\u0435, \u0441\u0442\u0430\u0440\u043e\u0439 \u043a\u043d\u0438\u0433\u043e\u0439, \u043a\u043e\u0444\u0435 \u0438 \u043f\u0440\u043e\u0447\u0438\u043c\u0438 \u043f\u043e\u0434\u043e\u0437\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0432\u0435\u0449\u0430\u043c\u0438.\n\n\u0422\u044b \u0437\u0430\u043c\u0435\u0447\u0430\u0435\u0448\u044c \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0432\u0441\u0435\u0433\u043e \u043a\u0440\u0430\u0441\u0438\u0432\u043e\u0433\u043e, \u0441\u043c\u0435\u0448\u043d\u043e\u0433\u043e \u0438 \u043d\u0435\u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e. \u0418\u043d\u043e\u0433\u0434\u0430 \u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0442\u044b \u043f\u0440\u043e\u0441\u0442\u043e \u0438\u0434\u0451\u0448\u044c \u043f\u043e \u0443\u043b\u0438\u0446\u0435, \u0430 \u0432\u043e\u043a\u0440\u0443\u0433 \u0442\u0435\u0431\u044f \u0443\u0436\u0435 \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043a\u0430\u043a\u0430\u044f-\u0442\u043e \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0430\u044f \u0438\u0441\u0442\u043e\u0440\u0438\u044f.\n\n\u0418 \u043c\u043d\u0435 \u043d\u0440\u0430\u0432\u0438\u0442\u0441\u044f \u0443\u0437\u043d\u0430\u0432\u0430\u0442\u044c \u044d\u0442\u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0438.\n\n\u0422\u044b \u0437\u0430\u043c\u0435\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f, \u041c\u0430\u0448. \u0422\u0432\u043e\u0440\u0447\u0435\u0441\u043a\u0430\u044f, \u0441\u043c\u0435\u043b\u0430\u044f, \u0441\u043c\u0435\u0448\u043d\u0430\u044f, \u0443\u043f\u0440\u044f\u043c\u0430\u044f \u0432 \u0445\u043e\u0440\u043e\u0448\u0435\u043c \u0441\u043c\u044b\u0441\u043b\u0435. \u0418 \u0443\u0434\u0438\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0436\u0438\u0432\u0430\u044f.\n\n\u041f\u0443\u0441\u0442\u044c \u0443 \u0442\u0435\u0431\u044f \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0432\u0441\u0451, \u0447\u0442\u043e \u0442\u044b \u0437\u0430\u0434\u0443\u043c\u0430\u043b\u0430. \u041f\u0443\u0441\u0442\u044c \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u0431\u043e\u043b\u044c\u0448\u0435 \u043a\u0440\u0430\u0441\u0438\u0432\u044b\u0445 \u043c\u0435\u0441\u0442, \u0445\u043e\u0440\u043e\u0448\u0438\u0445 \u043b\u044e\u0434\u0435\u0439, \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u044f \u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0435\u0439 \u0436\u0438\u0442\u044c \u0438\u043c\u0435\u043d\u043d\u043e \u0442\u0430\u043a, \u043a\u0430\u043a \u0442\u0435\u0431\u0435 \u0445\u043e\u0447\u0435\u0442\u0441\u044f.\n\n\u0418 \u043f\u0443\u0441\u0442\u044c \u043e\u0434\u043d\u0430\u0436\u0434\u044b \u0443 \u0442\u0432\u043e\u0435\u0439 \u043a\u043e\u0444\u0435\u0439\u043d\u0438 \u043f\u043e\u044f\u0432\u044f\u0442\u0441\u044f \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0435 \u0441\u0442\u0435\u043d\u044b, \u043e\u043a\u043d\u0430 \u0438 \u043a\u043b\u044e\u0447\u0438.\n\n\u0410 \u043f\u043e\u043a\u0430 \u0432\u043e\u0442.\n\n\u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f \u0442\u0432\u043e\u0435\u0439 \u043c\u0435\u0447\u0442\u044b.\n\n\u0421 \u0434\u043d\u0451\u043c \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f!");}else{locked=false;showToast("\u041a\u0430\u0436\u0435\u0442\u0441\u044f, \u0434\u043e\u043c \u0442\u0435\u0431\u044f \u043f\u0440\u0438\u0437\u043d\u0430\u043b. \u0422\u0435\u043f\u0435\u0440\u044c \u043c\u043e\u0436\u0435\u0448\u044c \u0445\u043e\u0437\u044f\u0439\u043d\u0438\u0447\u0430\u0442\u044c.");}}else{locked=false;updateQuest();}};
